/* Generated by scripts/split-content.mjs — do not edit by hand.
   The glossary and a sample of the question bank. The rest is served
   from the content function once entitlement is confirmed. */
window.DATA = {"cards":[{"id":"c000","term":"VPC (Virtual Private Cloud)","def":"An isolated virtual network within AWS where you define IP ranges, subnets, route tables, and gateways. The foundation of AWS network architecture.","cat":"Cloud","sub":"AWS SAP"},{"id":"c001","term":"Availability Zone (AZ)","def":"A physically separate data center within an AWS Region, with independent power, cooling, and networking. Designing across AZs provides high availability.","cat":"Cloud","sub":"AWS SAP"},{"id":"c002","term":"Region","def":"A geographic area containing two or more Availability Zones. Data residency, latency, and compliance requirements drive Region selection.","cat":"Cloud","sub":"AWS SAP"},{"id":"c003","term":"IAM (Identity and Access Management)","def":"AWS service for controlling who can do what. Uses users, groups, roles, and policies. Follows the principle of least privilege.","cat":"Cloud","sub":"AWS SAP"},{"id":"c004","term":"IAM Role","def":"An identity with permission policies that can be assumed by services, applications, or users. Preferred over long-lived credentials for cross-account and service access.","cat":"Cloud","sub":"AWS SAP"},{"id":"c005","term":"STS (Security Token Service)","def":"Issues temporary, limited-privilege credentials for IAM roles. Powers cross-account access and federation.","cat":"Cloud","sub":"AWS SAP"},{"id":"c006","term":"S3 (Simple Storage Service)","def":"Object storage with 11 nines of durability. Supports versioning, lifecycle policies, cross-region replication, and multiple storage classes.","cat":"Cloud","sub":"AWS SAP"},{"id":"c007","term":"S3 Storage Classes","def":"Standard, Intelligent-Tiering, Standard-IA, One Zone-IA, Glacier Instant Retrieval, Glacier Flexible Retrieval, Glacier Deep Archive — cost decreases as retrieval latency increases.","cat":"Cloud","sub":"AWS SAP"},{"id":"c008","term":"CloudFront","def":"AWS CDN that caches content at edge locations worldwide. Reduces latency and offloads origin servers. Supports signed URLs, Lambda@Edge, and Origin Access Control.","cat":"Cloud","sub":"AWS SAP"},{"id":"c009","term":"Route 53","def":"DNS service with health checks, routing policies (simple, weighted, latency, failover, geolocation, multivalue), and domain registration.","cat":"Cloud","sub":"AWS SAP"},{"id":"c010","term":"Auto Scaling Group (ASG)","def":"Automatically adjusts the number of EC2 instances based on demand using scaling policies. Maintains desired, minimum, and maximum capacity.","cat":"Cloud","sub":"AWS SAP"},{"id":"c011","term":"Elastic Load Balancer (ELB)","def":"Distributes traffic across targets. ALB operates at Layer 7 (HTTP), NLB at Layer 4 (TCP/UDP), GLB for third-party appliances.","cat":"Cloud","sub":"AWS SAP"},{"id":"c012","term":"Lambda","def":"Serverless compute that runs code in response to events. Billed per invocation and duration. Maximum 15-minute execution, 10 GB memory.","cat":"Cloud","sub":"AWS SAP"},{"id":"c013","term":"ECS / EKS","def":"Container orchestration services. ECS is AWS-native, EKS is managed Kubernetes. Both run on EC2 or Fargate (serverless containers).","cat":"Cloud","sub":"AWS SAP"},{"id":"c014","term":"RDS (Relational Database Service)","def":"Managed relational databases (MySQL, PostgreSQL, MariaDB, Oracle, SQL Server). Supports Multi-AZ for HA, read replicas for scaling reads.","cat":"Cloud","sub":"AWS SAP"},{"id":"c015","term":"Aurora","def":"AWS-built MySQL/PostgreSQL-compatible engine with up to 5x throughput. Storage auto-scales to 128 TB, replicates 6 copies across 3 AZs.","cat":"Cloud","sub":"AWS SAP"},{"id":"c016","term":"DynamoDB","def":"Fully managed NoSQL key-value and document database. Single-digit millisecond latency. Supports on-demand and provisioned capacity, global tables, and DAX caching.","cat":"Cloud","sub":"AWS SAP"},{"id":"c017","term":"ElastiCache","def":"Managed Redis or Memcached for in-memory caching. Reduces database load and improves read performance.","cat":"Cloud","sub":"AWS SAP"},{"id":"c018","term":"CloudFormation","def":"Infrastructure as Code service using JSON or YAML templates. Manages resource stacks with drift detection, change sets, and rollback.","cat":"Cloud","sub":"AWS SAP"},{"id":"c019","term":"Well-Architected Framework","def":"Six pillars guiding AWS architecture: Operational Excellence, Security, Reliability, Performance Efficiency, Cost Optimization, and Sustainability.","cat":"Cloud","sub":"AWS SAP"},{"id":"c020","term":"AWS Organizations","def":"Centralized management of multiple AWS accounts. Uses Service Control Policies (SCPs) to set permission boundaries across the organization.","cat":"Cloud","sub":"AWS SAP"},{"id":"c021","term":"Transit Gateway","def":"Hub that connects VPCs, VPNs, and Direct Connect in a hub-and-spoke model. Replaces complex VPC peering meshes.","cat":"Cloud","sub":"AWS SAP"},{"id":"c022","term":"Direct Connect","def":"Dedicated private network connection from on-premises to AWS. Lower latency and more consistent throughput than internet-based VPN.","cat":"Cloud","sub":"AWS SAP"},{"id":"c023","term":"KMS (Key Management Service)","def":"Creates and manages encryption keys. Integrates with most AWS services for at-rest encryption. Supports key rotation and custom key stores.","cat":"Cloud","sub":"AWS SAP"},{"id":"c024","term":"CloudTrail","def":"Records API calls across your AWS account. Essential for auditing, compliance, and security investigation.","cat":"Cloud","sub":"AWS SAP"},{"id":"c025","term":"CloudWatch","def":"Monitoring and observability service. Collects metrics, logs, and traces. Alarms trigger Auto Scaling, SNS notifications, or Lambda functions.","cat":"Cloud","sub":"AWS SAP"},{"id":"c026","term":"SNS / SQS","def":"SNS is pub/sub messaging (fan-out). SQS is a message queue (decoupling). Together they build resilient event-driven architectures.","cat":"Cloud","sub":"AWS SAP"},{"id":"c027","term":"EventBridge","def":"Serverless event bus that routes events between AWS services, SaaS apps, and custom applications using rules and event patterns.","cat":"Cloud","sub":"AWS SAP"},{"id":"c028","term":"Kinesis","def":"Real-time streaming data platform. Kinesis Data Streams for custom processing, Firehose for delivery to S3/Redshift/OpenSearch, Analytics for SQL on streams.","cat":"Cloud","sub":"AWS SAP"},{"id":"c029","term":"Cost Explorer / Budgets","def":"Cost Explorer visualizes spending patterns. Budgets set alerts on cost or usage thresholds. Together they enable cost governance.","cat":"Cloud","sub":"AWS SAP"},{"id":"c030","term":"GCP Project","def":"The fundamental organizational unit in Google Cloud. Resources, billing, APIs, and IAM are scoped to a project.","cat":"Cloud","sub":"GCP PCA"},{"id":"c031","term":"GCP Organization / Folder","def":"Organization is the root node for all projects. Folders group projects and apply policies hierarchically.","cat":"Cloud","sub":"GCP PCA"},{"id":"c032","term":"Compute Engine","def":"GCP IaaS virtual machines. Supports preemptible and spot VMs for cost savings, custom machine types, and sole-tenant nodes.","cat":"Cloud","sub":"GCP PCA"},{"id":"c033","term":"GKE (Google Kubernetes Engine)","def":"Managed Kubernetes service. Supports Autopilot (fully managed) and Standard (node-level control) modes.","cat":"Cloud","sub":"GCP PCA"},{"id":"c034","term":"Cloud Run","def":"Serverless container platform. Runs any containerized workload that listens on HTTP. Scales to zero, billed per request.","cat":"Cloud","sub":"GCP PCA"},{"id":"c035","term":"Cloud Functions","def":"Event-driven serverless functions. Triggered by HTTP, Pub/Sub, Cloud Storage events, Firestore changes, and more.","cat":"Cloud","sub":"GCP PCA"},{"id":"c036","term":"Cloud Storage","def":"Object storage with four classes: Standard, Nearline (30-day min), Coldline (90-day min), Archive (365-day min). Strongly consistent.","cat":"Cloud","sub":"GCP PCA"},{"id":"c037","term":"Cloud SQL / Cloud Spanner","def":"Cloud SQL: managed MySQL, PostgreSQL, SQL Server. Spanner: globally distributed, strongly consistent relational database with 99.999% SLA.","cat":"Cloud","sub":"GCP PCA"},{"id":"c038","term":"BigQuery","def":"Serverless data warehouse for analytics. Columnar storage, SQL interface, supports streaming inserts and federated queries across sources.","cat":"Cloud","sub":"GCP PCA"},{"id":"c039","term":"Pub/Sub","def":"Global messaging and event streaming service. Decouples publishers and subscribers. At-least-once delivery, supports push and pull.","cat":"Cloud","sub":"GCP PCA"},{"id":"c040","term":"VPC in GCP","def":"Global resource spanning all regions. Subnets are regional. Supports Shared VPC (cross-project networking) and VPC Peering.","cat":"Cloud","sub":"GCP PCA"},{"id":"c041","term":"Cloud IAM in GCP","def":"Binds members to roles on resources. Roles are primitive (owner/editor/viewer), predefined, or custom. Policy inheritance follows the resource hierarchy.","cat":"Cloud","sub":"GCP PCA"},{"id":"c042","term":"Cloud Armor","def":"DDoS protection and WAF for HTTP(S) load balancers. Supports IP allowlists/denylists, geo-based rules, and preconfigured WAF rules.","cat":"Cloud","sub":"GCP PCA"},{"id":"c043","term":"Anthos","def":"Platform for managing workloads across GKE, on-premises, and other clouds. Uses a consistent Kubernetes-based control plane.","cat":"Cloud","sub":"GCP PCA"},{"id":"c044","term":"Cloud CDN (GCP)","def":"Content delivery network integrated with HTTP(S) Load Balancing. Caches content at Google's global edge.","cat":"Cloud","sub":"GCP PCA"},{"id":"c045","term":"Azure Subscription","def":"A billing and access container for Azure resources. Resources are grouped into Resource Groups within a subscription.","cat":"Cloud","sub":"Azure SA"},{"id":"c046","term":"Resource Group","def":"A logical container for Azure resources that share a lifecycle. Policies, RBAC, and tags are commonly applied at this level.","cat":"Cloud","sub":"Azure SA"},{"id":"c047","term":"Azure AD / Entra ID","def":"Cloud identity and access management service. Handles authentication, single sign-on, conditional access, and MFA.","cat":"Cloud","sub":"Azure SA"},{"id":"c048","term":"Azure RBAC","def":"Role-Based Access Control at the management group, subscription, resource group, or resource level. Built-in roles plus custom role support.","cat":"Cloud","sub":"Azure SA"},{"id":"c049","term":"Virtual Network (VNet)","def":"Isolated network in Azure with subnets, NSGs, route tables, and peering. VNet peering connects VNets across regions.","cat":"Cloud","sub":"Azure SA"},{"id":"c050","term":"Azure Load Balancer / App Gateway","def":"Load Balancer operates at Layer 4. Application Gateway is a Layer 7 load balancer with WAF, URL routing, and SSL termination.","cat":"Cloud","sub":"Azure SA"},{"id":"c051","term":"Azure Functions","def":"Serverless compute triggered by events. Supports consumption (scale-to-zero) and premium (pre-warmed) plans.","cat":"Cloud","sub":"Azure SA"},{"id":"c052","term":"Azure Kubernetes Service (AKS)","def":"Managed Kubernetes with integrated CI/CD, monitoring, and Azure AD integration. Control plane is free; you pay for nodes.","cat":"Cloud","sub":"Azure SA"},{"id":"c053","term":"Cosmos DB","def":"Globally distributed, multi-model NoSQL database. Supports five consistency levels from strong to eventual. Single-digit millisecond latency.","cat":"Cloud","sub":"Azure SA"},{"id":"c054","term":"Azure SQL / SQL Managed Instance","def":"Azure SQL Database is a fully managed PaaS. Managed Instance provides near-complete SQL Server engine compatibility for lift-and-shift.","cat":"Cloud","sub":"Azure SA"},{"id":"c055","term":"Blob Storage","def":"Azure object storage with Hot, Cool, Cold, and Archive access tiers. Supports immutable storage, versioning, and lifecycle management.","cat":"Cloud","sub":"Azure SA"},{"id":"c056","term":"Azure Front Door","def":"Global load balancer and CDN with WAF, SSL offloading, URL-based routing, and session affinity. Routes to the fastest healthy backend.","cat":"Cloud","sub":"Azure SA"},{"id":"c057","term":"ExpressRoute","def":"Dedicated private connection from on-premises to Azure via a connectivity provider. Does not traverse the public internet.","cat":"Cloud","sub":"Azure SA"},{"id":"c058","term":"ARM Templates / Bicep","def":"Infrastructure as Code for Azure. ARM templates are JSON; Bicep is a cleaner DSL that compiles to ARM. Both deploy and manage resource stacks.","cat":"Cloud","sub":"Azure SA"},{"id":"c059","term":"Azure Monitor / Log Analytics","def":"Azure Monitor collects metrics and logs. Log Analytics workspace stores and queries logs using KQL (Kusto Query Language).","cat":"Cloud","sub":"Azure SA"},{"id":"c060","term":"Azure Policy","def":"Enforces organizational standards across resources. Policies can audit, deny, or remediate non-compliant configurations.","cat":"Cloud","sub":"Azure SA"},{"id":"c061","term":"Azure Landing Zone","def":"A prescriptive architecture for setting up a multi-subscription Azure environment with governance, networking, identity, and security baselines.","cat":"Cloud","sub":"Azure SA"},{"id":"c062","term":"Shared Responsibility Model","def":"The cloud provider secures the infrastructure; the customer secures what they put on it. The boundary shifts depending on IaaS, PaaS, or SaaS.","cat":"Cloud","sub":"Cross-Cloud"},{"id":"c063","term":"IaaS / PaaS / SaaS","def":"Infrastructure, Platform, and Software as a Service. Each moves more responsibility to the provider and less to the customer.","cat":"Cloud","sub":"Cross-Cloud"},{"id":"c064","term":"Multi-Region Architecture","def":"Deploying across multiple geographic regions for disaster recovery and low latency. Requires data replication, DNS-based routing, and conflict resolution.","cat":"Cloud","sub":"Cross-Cloud"},{"id":"c065","term":"RPO / RTO","def":"Recovery Point Objective: how much data loss is acceptable. Recovery Time Objective: how long until service is restored. Together they define DR requirements.","cat":"Cloud","sub":"Cross-Cloud"},{"id":"c066","term":"Infrastructure as Code (IaC)","def":"Managing and provisioning infrastructure through machine-readable configuration files rather than manual processes. Enables version control, testing, and repeatability.","cat":"Cloud","sub":"Cross-Cloud"},{"id":"c067","term":"GitOps","def":"Operational model where Git is the single source of truth for declarative infrastructure and applications. Changes are applied via pull requests and automated reconciliation.","cat":"Cloud","sub":"Cross-Cloud"},{"id":"c068","term":"Service Mesh","def":"Infrastructure layer handling service-to-service communication. Provides mutual TLS, traffic management, observability, and retries. Examples: Istio, Linkerd.","cat":"Cloud","sub":"Cross-Cloud"},{"id":"c069","term":"CAP Theorem","def":"A distributed data system can guarantee at most two of Consistency, Availability, and Partition tolerance. Network partitions are unavoidable, so the real choice is C or A during a partition.","cat":"Cloud","sub":"Cross-Cloud"},{"id":"c070","term":"Eventual Consistency","def":"After a write, reads may not immediately return the latest value, but the system converges over time. Used in highly available distributed systems.","cat":"Cloud","sub":"Cross-Cloud"},{"id":"c071","term":"Blue/Green Deployment","def":"Maintaining two identical environments. Traffic is switched from the current (blue) to the new (green) once validated. Enables instant rollback.","cat":"Cloud","sub":"Cross-Cloud"},{"id":"c072","term":"Canary Deployment","def":"Rolling out a change to a small subset of users or instances before full rollout. Limits blast radius if the change introduces an issue.","cat":"Cloud","sub":"Cross-Cloud"},{"id":"c073","term":"12-Factor App","def":"Methodology for building SaaS applications. Key principles: config in environment, stateless processes, port binding, disposability, dev/prod parity, logs as event streams.","cat":"Cloud","sub":"Cross-Cloud"},{"id":"c074","term":"FinOps","def":"Practice of bringing financial accountability to cloud spending. Combines engineering, finance, and business to optimize cloud value.","cat":"Cloud","sub":"Cross-Cloud"}],"questions":[{"cat":"Cloud","sub":"AWS SAP","stem":"A company needs to serve static assets to users globally with the lowest latency. Which combination should the architect recommend?","choices":["RDS read replicas with Route 53","S3 with CloudFront distribution","EBS volumes with cross-region replication","EC2 instances in every region"],"answer":1,"label":"S3 + CloudFront","why":"S3 provides durable object storage and CloudFront caches at edge locations worldwide, minimizing latency without managing servers.","id":"q001","n":1},{"cat":"Cloud","sub":"AWS SAP","stem":"An application running on EC2 needs to access an S3 bucket in another AWS account without long-lived credentials. The correct approach is:","choices":["Use the root account credentials of the other account","Store the other account's credentials in Systems Manager Parameter Store","Create an IAM user in the other account and share the access keys","Create a cross-account IAM role and have the application assume it via STS"],"answer":3,"label":"Cross-account IAM role","why":"IAM roles with STS provide temporary credentials, eliminating the security risk of shared long-lived access keys.","id":"q002","n":2},{"cat":"Cloud","sub":"AWS SAP","stem":"A solutions architect is designing a highly available web application. The architecture should survive the loss of an entire Availability Zone. The minimum design requires:","choices":["A single EC2 instance with an Elastic IP","EC2 instances in two Regions with Route 53 failover","EC2 instances in two AZs behind an Application Load Balancer","A single AZ with Auto Scaling"],"answer":2,"label":"Multi-AZ with ALB","why":"Multi-AZ deployment ensures that if one AZ fails, the load balancer routes traffic to healthy instances in the remaining AZ.","id":"q003","n":3},{"cat":"Cloud","sub":"AWS SAP","stem":"An organization stores sensitive data in S3 and must ensure that objects are encrypted at rest using keys they manage and can rotate on their own schedule. They should use:","choices":["Client-side encryption only","S3 bucket policies without encryption","Server-side encryption with AWS KMS customer-managed keys","S3 default encryption with SSE-S3"],"answer":2,"label":"SSE-KMS with CMK","why":"Customer-managed KMS keys give the organization full control over key rotation, access policies, and audit trails via CloudTrail.","id":"q004","n":4},{"cat":"Cloud","sub":"AWS SAP","stem":"A company is migrating a legacy application that requires a relational database with minimal code changes. The database must support automatic failover. The best option is:","choices":["Aurora Multi-AZ with automatic failover","ElastiCache with Redis cluster mode","DynamoDB with global tables","S3 with versioning"],"answer":0,"label":"Aurora Multi-AZ","why":"Aurora is MySQL/PostgreSQL-compatible, minimizing code changes, and Multi-AZ provides automatic failover with a replica promotion time under 30 seconds.","id":"q005","n":5},{"cat":"Cloud","sub":"AWS SAP","stem":"A workload processes messages that must not be lost and must be handled exactly once. The decoupling service should be:","choices":["SQS FIFO queue with exactly-once processing","Kinesis Data Streams","SNS with standard topics","A shared database table as a queue"],"answer":0,"label":"SQS FIFO","why":"SQS FIFO queues guarantee exactly-once processing and message ordering, which standard queues and SNS do not.","id":"q006","n":6},{"cat":"Cloud","sub":"AWS SAP","stem":"An architect needs to connect 15 VPCs that must communicate with each other and with an on-premises data center. The simplest approach is:","choices":["A single large VPC with 15 subnets","Full-mesh VPC peering","A Transit Gateway with VPN or Direct Connect attachments","Network Load Balancers in each VPC"],"answer":2,"label":"Transit Gateway","why":"Transit Gateway acts as a hub, avoiding the N*(N-1)/2 peering connections a full mesh would require. VPN or Direct Connect attaches the on-premises network.","id":"q007","n":7},{"cat":"Cloud","sub":"AWS SAP","stem":"A startup wants to run containers without managing servers or clusters. They need per-request billing with minimal operational overhead. They should use:","choices":["ECS on Fargate","Self-managed Kubernetes on EC2","EC2 with Docker installed","Lambda with container image support"],"answer":0,"label":"ECS on Fargate","why":"Fargate removes server and cluster management entirely. ECS on Fargate bills per vCPU and memory per second, matching the requirement.","id":"q008","n":8},{"cat":"Cloud","sub":"AWS SAP","stem":"An organization must restrict all member accounts from launching resources outside of us-east-1 and eu-west-1. This is enforced by:","choices":["VPC endpoint policies","Service Control Policies in AWS Organizations","IAM policies on each user","Security groups"],"answer":1,"label":"SCPs in Organizations","why":"Service Control Policies set permission boundaries across an entire organization or organizational unit, regardless of individual IAM policies.","id":"q009","n":9},{"cat":"Cloud","sub":"AWS SAP","stem":"A data lake on S3 stores petabytes of data with varying access patterns. Some data is accessed daily, some monthly, some rarely. The cost-optimization strategy is:","choices":["Create separate buckets for each access pattern","Store everything in S3 Standard","Store everything in Glacier","Use S3 Intelligent-Tiering"],"answer":3,"label":"S3 Intelligent-Tiering","why":"Intelligent-Tiering automatically moves objects between access tiers based on changing access patterns, optimizing cost without operational overhead.","id":"q010","n":10}],"meta":{"total":29,"free":10,"split":true}};
